{
  "microtasks": [
    {
      "id": 1,
      "description": "Create an outline for the Scope and Limitations section, dividing it into subsections for scope (inclusions) and limitations (exclusions).",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Draft the scope paragraph defining the target population (adolescents) and the specific setting (high school students from partner schools).",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Draft the scope paragraph defining the specific variables of interest (peer pressure and risk-taking behavior) to be examined.",
      "prerequisites": [1]
    },
    {
      "id": 4,
      "description": "Draft the limitation paragraph explaining how restricting the sample to partner schools limits the generalizability of the findings.",
      "prerequisites": [2]
    },
    {
      "id": 5,
      "description": "Draft the limitation paragraph explaining the temporal constraint of not measuring long-term behavioral outcomes beyond the current school year.",
      "prerequisites": [1]
    },
    {
      "id": 6,
      "description": "Integrate the drafted scope and limitation paragraphs into a single, cohesive section with smooth transitions.",
      "prerequisites": [3, 4, 5]
    },
    {
      "id": 7,
      "description": "Review and edit the integrated section for academic tone, clarity, and alignment with the overall research paper.",
      "prerequisites": [6]
    }
  ]
}
